from abc import ABC, abstractmethod
from decimal import Decimal
from datetime import datetime


class FareCalculator(ABC):
    """Абстрактный калькулятор тарифа."""

    @abstractmethod
    def calculate(self, card_id: str) -> Decimal:
        """Рассчитать стоимость проезда для данной карты."""
        ...


class StandardFare(FareCalculator):
    """Стандартный тариф: 150 тенге."""

    def calculate(self, card_id: str) -> Decimal:
        return Decimal("150")


class StudentFare(FareCalculator):
    """Студенческий тариф: 75 тенге."""

    def calculate(self, card_id: str) -> Decimal:
        return Decimal("75")


class TransactionLogger(ABC):
    """Абстрактный логгер транзакций."""

    @abstractmethod
    def log(self, card_id: str, amount: Decimal) -> None:
        """Записать информацию о транзакции."""
        ...


class ConsoleLogger(TransactionLogger):
    """Логгер, выводящий транзакции в консоль."""

    def log(self, card_id: str, amount: Decimal) -> None:
        print(f"Transaction: card={card_id}, amount={amount}")


class TripProcessor:
    """Обработчик поездок, собранный через Dependency Injection."""

    def __init__(self, calculator: FareCalculator,
                 logger: TransactionLogger) -> None:
        self._calculator = calculator
        self._logger = logger

    def process(self, card_id: str, balance: Decimal,
                last_trip_time: datetime | None = None) -> dict:
        """Обработать поездку."""
        fare = self._calculator.calculate(card_id)

        if last_trip_time is not None:
            elapsed = (datetime.now() - last_trip_time).total_seconds()
            if elapsed <= 3600:
                fare = Decimal("0")

        if balance < fare:
            return {"status": "error", "message": "Недостаточно средств"}

        new_balance = balance - fare
        self._logger.log(card_id, fare)

        return {
            "status": "success",
            "fare": fare,
            "new_balance": new_balance,
        }


def create_trip_processor(calculator: FareCalculator | None = None,
                          logger: TransactionLogger | None = None
                          ) -> TripProcessor:
    """Собрать TripProcessor с зависимостями по умолчанию."""
    if calculator is None:
        calculator = StandardFare()
    if logger is None:
        logger = ConsoleLogger()
    return TripProcessor(calculator=calculator, logger=logger)
